pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score on remaining space after placement
    let mut score = post_residual as f64;

    // 1. Perfect fit bonus
    if post_residual == 0 {
        score -= 4_200.0;
    }

    // 2. Residual ratio: prefer bins that are almost full
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio >= 0.97 {
        score -= 450.0;
    } else if ratio <= 0.05 {
        score += 180.0;
    }

    // 3. Gap relative to next item (lookahead)
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // cannot fit next item: penalise by gap size
            score += (diff as f64) * 28.0;
        } else {
            // can fit next item: reward by leaving small gap
            score -= (-diff as f64) * 12.0;
        }
    }

    // 4. Mean residual proximity (non‑linear)
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= mean_diff * 0.9;

    // 5. Open bins penalty – encourage reuse
    score += (open_bins_count as f64) * 5.0;

    // 6. Fitting bins count: very few bins is good, too many is bad
    if fitting_bins_count <= 2 {
        score -= 250.0;
    } else if fitting_bins_count > 5 {
        score += 55.0;
    }

    // 7. New bin decision
    if bin_residual == bin_capacity {
        let threshold = (total_items as f64 / 28.0).ceil() as usize;
        if open_bins_count > threshold {
            score += 420.0;
        } else {
            score -= 70.0;
        }
    }

    // 8. Late‑stream tolerance
    if step_index > total_items * 8 / 10 {
        score -= 260.0;
    }

    // 9. Large item bias
    if item_size > bin_capacity / 2 && post_residual < 8 {
        score -= 140.0;
    } else if item_size > bin_capacity / 3 && post_residual < 18 {
        score -= 80.0;
    }

    // 10. Lookahead via mean residual (refined)
    if post_residual < mean_residual as u32 {
        score += 110.0;
    } else if post_residual > (mean_residual + 15.0) as u32 {
        score -= 25.0;
    }

    // 11. Occupancy ratio adjustment
    let occupancy = bin_capacity - bin_residual;
    let occ_ratio = occupancy as f64 / bin_capacity as f64;
    if occ_ratio > 0.85 {
        score -= 240.0;
    } else if occ_ratio < 0.15 {
        score += 130.0;
    }

    // 12. Early use encouragement
    if open_bins_count < 2 {
        score -= 25.0;
    } else if open_bins_count > 6 {
        score += 35.0;
    }

    // 13. Residual variance tweak
    if post_residual < (mean_residual - 5.0) as u32 {
        score -= 45.0;
    } else if post_residual > (mean_residual + 5.0) as u32 {
        score += 30.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base on remaining space
    let mut score = post_residual as f64;

    // 1. Perfect fit: huge bonus
    if post_residual == 0 {
        score -= 3_000.0;
    }

    // 2. Residual ratio checks (almost full vs. almost empty)
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio >= 0.95 {
        score -= 200.0; // almost full
    } else if ratio <= 0.02 {
        score += 400.0; // too little left
    }

    // 3. Gap relative to next item
    if next_item_size > 0 {
        let diff = next_item_size as i32 - post_residual as i32;
        if diff > 0 {
            // cannot fit next item: penalty grows with the gap
            score += diff as f64 * 20.0;
        } else {
            // can fit next item: slight reward for extra space
            score -= (-diff as f64) * 10.0;
        }
    }

    // 4. Proximity to mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score -= mean_diff * 0.6;

    // 5. Open bins penalty
    score += (open_bins_count as f64) * 5.0;

    // 6. Fitting bins bonus/penalty
    if fitting_bins_count == 1 {
        score -= 500.0;
    } else if fitting_bins_count > 6 {
        score += 100.0;
    }

    // 7. New bin penalty when many bins already open
    if bin_residual == bin_capacity {
        let threshold = (total_items as f64 / 20.0) as usize;
        if open_bins_count > threshold {
            score += 600.0;
        }
    }

    // 8. Late‑stream tolerance
    if step_index > total_items * 8 / 10 {
        score -= 250.0;
    }

    // 9. Large item bias for moderately full bins
    if item_size > bin_capacity / 3 && post_residual < 15 {
        score -= 90.0;
    }

    // 10. Lookahead via mean residual
    if post_residual < mean_residual as u32 {
        score += 150.0;
    } else if post_residual > (mean_residual + 25.0) as u32 {
        score -= 40.0;
    }

    // 11. Encourage early use of a few bins
    if open_bins_count < 4 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placement
    let mut score = post_residual as f64;

    // Reward a perfect fit heavily
    if post_residual == 0 {
        score -= 1500.0;
    }

    // Penalize very small gaps that cannot accommodate the next item
    if post_residual < 10 {
        score += 800.0; // harsh penalty for dead space
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 400.0; // penalty if the next item would have to open a new bin
    }

    // Penalize using a bin when many bins are already open
    // This pushes the algorithm to keep the number of open bins low
    score += (open_bins_count as f64) * 4.0;

    // Reward bins that are the sole candidate for this item
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // Slightly reward residuals close to the mean residual to keep load balanced
    let diff = (post_residual as f64 - mean_residual).abs();
    score -= diff * 0.2;

    // Slightly penalize large residuals to avoid waste when possible
    if post_residual > 40 {
        score += 100.0;
    }

    // Return the final score – lower is better
    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Start from the residual after placing the item
    let mut score = post_residual as f64;

    // ---------- Perfect fit ----------
    if post_residual == 0 {
        score -= 2_800.0;
    }

    // ---------- Residual ratio ----------
    let res_ratio = post_residual as f64 / bin_capacity as f64;
    if res_ratio < 0.02 {
        score += 250.0; // almost full but not perfect
    } else if res_ratio < 0.07 {
        score += 120.0; // tight
    } else if res_ratio > 0.92 {
        score -= 250.0; // too full, wasteful
    }

    // ---------- Mean‑residual proximity ----------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.35;

    // ---------- Residual variance penalty ----------
    let variance_penalty = ((post_residual as f64 - mean_residual).powi(2)) * 0.012;
    score += variance_penalty;

    // ---------- Open bins count ----------
    score += (open_bins_count as f64).powi(2) * 0.015;

    // ---------- Fitting bins handling ----------
    if fitting_bins_count == 1 {
        score -= 280.0;
    } else if fitting_bins_count > 8 {
        score += 70.0;
    }

    // ---------- Next‑item lookahead ----------
    if next_item_size > 0 {
        // If current bin cannot fit next item, penalise heavily
        if post_residual < next_item_size {
            score += 220.0;
            // Larger next item gets an extra penalty
            if next_item_size > item_size {
                score += 90.0;
            }
        } else {
            // Reward a margin that can accommodate next item
            let margin = post_residual - next_item_size;
            score -= (margin as f64) * 0.06;
        }
    }

    // ---------- End‑of‑stream ----------
    if step_index > (total_items * 9 / 10) {
        score -= 120.0;
    }

    // ---------- Large item in a big bin ----------
    if item_size > bin_capacity / 2 && post_residual < 6 {
        score -= 90.0;
    }

    // ---------- New bin special handling ----------
    if bin_residual == bin_capacity {
        let new_residual = bin_capacity - item_size;
        let mut new_score = new_residual as f64;
        if new_residual == 0 {
            new_score -= 2_800.0;
        }
        // Penalise opening new bin if many bins already exist
        if open_bins_count > ((total_items as f64) / 15.0) as usize {
            new_score += 350.0;
        }
        // Prefer new bin only if it yields a better score
        if new_score < score {
            score = new_score;
        }
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
