    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // Heavy reward for a perfect fit
    if post_residual == 0 {
        score -= 2000.0;
    }

    // Small gaps that cannot hold the next item are heavily penalised
    if post_residual < 5 {
        score += 1200.0;
    } else if post_residual < 15 {
        score += 600.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 300.0;
    }

    // Penalise using a bin when many are already open
    score += (open_bins_count as f64) * 3.0;

    // If this is the only candidate, give a bonus
    if fitting_bins_count == 1 {
        score -= 350.0;
    }

    // Ratio of residual to capacity – reward nearly full bins, punish almost empty ones
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio < 0.05 {
        score += 500.0;
    } else if residual_ratio > 0.9 {
        score -= 200.0;
    }

    // Keep residuals close to the mean
    let diff = (post_residual as f64 - mean_residual).abs();
    score -= diff * 0.3;

    // Avoid large waste when possible
    if post_residual > 60 {
        score += 150.0;
    }

    // Look‑ahead: if the next item will fit, try to keep enough margin
    if next_item_size > 0 && post_residual >= next_item_size {
        let margin = post_residual - next_item_size;
        score -= (margin as f64) * 0.05;
    }

    // Penalise opening a brand‑new bin when many bins are already open
    if bin_residual == bin_capacity
        && open_bins_count > ((total_items as f64) / 20.0) as usize
    {
        score += 500.0;
    }

    // Near the end of the stream, be more tolerant of waste
    if step_index > (total_items * 9 / 10) {
        score -= 200.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the remaining space after placing the item
    let mut score = post_residual as f64;

    // Penalize dead space when the next item cannot fit into this bin
    if next_item_size > 0 && post_residual < next_item_size {
        score += 200.0;
    }

    // Penalize or reward based on how the residual compares to the current mean
    let mean_diff = post_residual as f64 - mean_residual;
    if mean_diff > 0.0 {
        score += mean_diff * 0.5; // larger than mean → penalty
    } else {
        score += mean_diff * 0.2; // smaller than mean → slight reward (negative)
    }

    // Penalize high residual relative to the bin capacity
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio * 5.0;

    // Early in the stream we penalize residual more aggressively
    let progress = step_index as f64 / total_items as f64;
    let time_weight = 1.0 - progress; // 1.0 at start, 0.0 at end
    score += time_weight * (post_residual as f64 * 0.05);

    // If many bins are open, we slightly encourage tighter packing
    if open_bins_count > 0 {
        score -= (open_bins_count as f64) * 0.1;
    }

    // Reward the bin if it is the only one that can fit and it gives a perfect fit
    if fitting_bins_count == 1 && bin_residual == item_size {
        score -= 10.0;
    }

    score
}

