pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit – strongly rewarded.
    if post_residual == 0 {
        score -= 4_000.0;
    }

    // Tiny gaps are heavily penalised.
    if post_residual < 1 {
        score += 3_000.0;
    } else if post_residual < 3 {
        score += 1_500.0;
    }

    // Large residual waste is penalised.
    if post_residual > 80 {
        score += 200.0;
    }

    // Open‑bin pressure – encourage packing into existing bins.
    score += (open_bins_count as f64) * 3.0;

    // Only one viable bin – strongly incentivised.
    if fitting_bins_count == 1 {
        score -= 600.0;
    }

    // Residual ratio extremes – avoid very empty or almost full bins.
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio < 0.05 {
        score += 500.0;
    } else if ratio > 0.95 {
        score -= 200.0;
    }

    // Keep residuals close to the running mean.
    let diff = (post_residual as f64 - mean_residual).abs();
    score -= diff * 0.8;

    // Next‑item margin handling.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let margin = post_residual - next_item_size;
            score -= (margin as f64) * 0.2;
        } else {
            score += 700.0 + (next_item_size - post_residual) as f64 * 1.0;
        }
    }

    // New‑bin penalty when many bins are open.
    if bin_residual == bin_capacity
        && open_bins_count > (total_items as f64 / 12.0) as usize
    {
        score += 400.0;
    }

    // Late‑stream tolerance – be more forgiving of waste.
    if step_index > (total_items * 9 / 10) {
        score -= 200.0;
    }

    // Large item bias for moderately full bins.
    if item_size > bin_capacity / 2 && post_residual < 15 {
        score -= 100.0;
    }

    // Overfull relative to the next item when many bins are available.
    if fitting_bins_count > 4 && next_item_size > 0 && post_residual < next_item_size {
        score += 120.0;
