            if post_residual - next_item_size > 3 {
                score += 5.0;
            }
        } else {
            let diff = (next_item_size - post_residual) as f64;
            score += 60.0 * diff * diff / bin_capacity as f64;
        }
    }

    // 5. Mean‑residual alignment
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.25 * diff;          // over‑filled
    } else {
        score -= 0.15 * -diff;         // under‑filled
    }

    // 6. Open‑bin pressure (sub‑linear)
    if open_bins_count > 3 {
        score += 3.0 * ((open_bins_count - 3) as f64).sqrt();
    }
    if open_bins_count > 6 {
        score += 6.0 * ((open_bins_count - 6) as f64).sqrt();
    }

    // 7. Progress‑dependent end‑of‑stream cost
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
        score += 1.0 * post_residual as f64;
    }

    // 8. Fitting‑bin count signal
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 4 {
        score += 3.0;
    }

    // 9. New‑bin bias for large items
    if bin_residual == bin_capacity {
        if item_size > 80 {
            score -= 18.0;
        } else {
            score += 1.0;
        }
    }

    // 10. Residual squared contribution (soft)
    score += 0.01 * (post_residual as f64).powi(2);

    // 11. Bin‑residual size signal
    let residual_pct = bin_residual as f64 / bin_capacity as f64;
    if residual_pct > 0.8 && item_size <= bin_residual {
        score -= 3.0;
    } else if residual_pct < 0.2 && item_size > bin_residual {
        score += 3.0;
    }

    // 12. Ideal residual bias (~40% of capacity)
    let ideal = bin_capacity as f64 * 0.40;
    let idle = (post_residual as f64 - ideal).abs();
    if idle > 5.0 {
        score += 0.06 * idle;
    }

    // 13. Late‑stage new‑bin pressure
    if open_bins_count > 4 && bin_residual < 8 && item_size > bin_residual {
        score += 3.0;
    }

    // 14. Compactness reward for tight bins
    if post_residual < 5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: residual after placement
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // 1. Residual ratio (tighter packing)
    let ratio = post_residual as f64 / bin_capacity as f64;
    score += 2.5 * ratio.powi(2) + 1.8 * ratio;

    // ------------------------------------------------------------------
    // 2. Look‑ahead waste penalty / reward
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Not enough space for next item – heavy penalty
            score += 70.0 * (next_item_size - post_residual) as f64;
        } else if post_residual > next_item_size + 4 {
            // Plenty of space – small reward
            let slack = (post_residual - next_item_size - 4) as f64;
            score -= 25.0 * slack / bin_capacity as f64;
        }
    }

    // ------------------------------------------------------------------
    // 3. Mean‑residual alignment
    let diff = post_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += 0.4 * diff;
    } else {
        score -= 0.6 * (-diff);
    }

    // ------------------------------------------------------------------
    // 4. Open‑bin pressure
    if open_bins_count > 3 {
        score += 3.5 * ((open_bins_count - 3) as f64);
    }
    if open_bins_count > 7 {
        score += 5.0 * ((open_bins_count - 7) as f64);
    }

    // ------------------------------------------------------------------
    // 5. End‑of‑stream cost
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
        score += 3.0 * post_residual as f64;
    }

    // ------------------------------------------------------------------
    // 6. Fitting‑bin count signal
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 5 {
        score += 6.0;
    }

    // ------------------------------------------------------------------
    // 7. New‑bin bias for large items
    if bin_residual == bin_capacity {
        if item_size > 85 {
            score -= 45.0;
        } else if item_size > 65 {
            score -= 12.0;
        } else {
            score += 1.0;
        }
    }

    // ------------------------------------------------------------------
    // 8. Quadratic penalty for deviation from mean
    score += 0.04 * diff * diff;

    // ------------------------------------------------------------------
    // 9. Residual squared contribution
    score += 0.02 * (post_residual as f64).powi(2);

    // ------------------------------------------------------------------
    // 10. Residual pct signal
    let residual_pct = bin_residual as f64 / bin_capacity as f64;
    if residual_pct > 0.75 && item_size <= bin_residual {
        score -= 4.0;
    } else if residual_pct < 0.25 && item_size > bin_residual {
        score += 6.0;
    }

    // ------------------------------------------------------------------
    // 11. Ideal‑residual bias – target ~48%
    let ideal_residual = bin_capacity as f64 * 0.48;
    let idle = (post_residual as f64 - ideal_residual).abs();
    if idle > 4.0 {
        score += 0.10 * idle;
    }

    // ------------------------------------------------------------------
    // 12. Late‑stage new‑bin pressure
    if open_bins_count > 2 && bin_residual < 6 && item_size > bin_residual {
        score += 2.5;
    }

    // ------------------------------------------------------------------
    // 13. Final aggressive closing near end
    if total_items - step_index < 2 && open_bins_count > 1 {
        score += 3.0 * ((open_bins_count - 1) as f64);
    }

    // ------------------------------------------------------------------
    // 14. Look‑ahead fit reward (leaving space for next item)
    if next_item_size > 0 && bin_residual - item_size >= next_item_size + 2 {
        score -= 5.0;
    }

    // ------------------------------------------------------------------
    // 15. No‑fit penalty
    if fitting_bins_count == 0 {
        score += 12.0;
    }

    // ------------------------------------------------------------------
    // 16. Excess slack penalty
    if post_residual as f64 > mean_residual * 1.5 {
        score += 0.02 * (post_residual as f64 - mean_residual * 1.5);
    }

    score
}

