        score -= 2.5;
    } else if post_residual <= 5 {
        score -= 1.5;
    }

    // Penalise very large gaps
    if post_residual > 60 {
        score += 0.003 * ((post_residual - 60) as f64).powi(2);
    }

    // Look‑ahead penalty
    if post_residual < next_item_size {
        score += 4.0 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 95 && post_residual < 8 {
        score += 15.0;
    }

    // Pressure from many open bins
    score += 0.3 * open_bins_count as f64;
    if open_bins_count > 10 {
        score += 5.0;
    }

    // Incentive for many fitting bins
    if fitting_bins_count >= 5 {
        score -= 2.0;
    } else if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // New‑bin handling
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 1.5 * (open_bins_count as f64).sqrt() + 0.5;
    }

    // Align with mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff > 10.0 {
        score += mean_diff * 0.05;
    } else {
        score -= 0.6;
    }

    // Progress‑based relaxation
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 1.5;

    // Residual ratio bonus/penalty
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.8 {
        score += 10.0 * (ratio - 0.8);
    } else if ratio < 0.2 {
        score -= 3.0 * (0.2 - ratio);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
