    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score from the residual after placement
    let mut score = post_residual as f64;

    // Small gaps are highly valuable
    if post_residual <= 2 {
        score -= 4.0;
    } else if post_residual <= 5 {
        score -= 2.0;
    }

    // Penalise very large gaps with a steeper quadratic
    if post_residual > 80 {
        score += 0.005 * ((post_residual - 80) as f64).powi(2);
    }

    // Residual ratio bonus/penalty
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.90 {
        score += 15.0 * (ratio - 0.90);
    } else if ratio < 0.10 {
        score -= 5.0 * (0.10 - ratio);
    }

    // Look‑ahead handling – penalise gaps that would force a future item
    if next_item_size > post_residual {
        score += 4.0 * (next_item_size - post_residual) as f64;
    } else {
        score -= 1.0 * ((next_item_size as f64 - post_residual as f64).abs());
    }

    // Align with the mean residual – tighter packing gets a bonus
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff < 3.0 {
        score -= 2.0;
    } else {
        score += 0.03 * mean_diff;
    }

    // Pressure from many open bins – encourage using existing bins
    score += 0.30 * open_bins_count as f64;
    if open_bins_count > 10 {
        score += 3.0;
    }

    // Incentive for bins that can fit many items
    if fitting_bins_count >= 5 {
        score -= 3.0;
    } else if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // New‑bin handling – prefer a new bin only when no good fit exists
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 1.5 * (open_bins_count as f64).sqrt();
        } else {
            score -= 3.0;
        }
    }

    // Progress‑based relaxation – later in the stream we are more tolerant
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 1.0;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base: penalize the amount of unused space after placement
    let mut score = 0.6 * post_residual as f64;

    // Highly desirable tiny gaps
    if post_residual <= 3 {
        score -= 4.0;
    } else if post_residual <= 6 {
        score -= 2.0;
    } else if post_residual <= 10 {
        score -= 0.5;
    }

    // Quadratic penalty for large gaps
    if post_residual > 70 {
        let excess = post_residual - 70;
        score += 0.003 * (excess as f64).powi(2);
    }

    // Residual ratio bonus/penalty
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.75 {
        score += 10.0 * (ratio - 0.75);
    } else if ratio < 0.20 {
        score -= 5.0 * (0.20 - ratio);
    }

    // Look‑ahead: prefer bins that leave a residual close to the next item
    if next_item_size > post_residual {
        score += 4.0 * (next_item_size - post_residual) as f64;
    } else {
        score -= 0.9 * (next_item_size as f64 - post_residual as f64).abs();
    }

    // Align with the mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff < 3.0 {
        score -= 2.0;
    } else {
        score += 0.015 * mean_diff;
    }

    // Pressure from many open bins: encourage using bins that can fit many items,
    // but penalise an excessive open‑bin count.
    if fitting_bins_count >= 5 {
        score -= 3.0;
    } else if fitting_bins_count == 1 {
        score -= 4.0;
    }
    score += 0.3 * open_bins_count as f64;
    if open_bins_count > 15 {
        score += 5.0;
    }

    // New‑bin handling: only open a new bin when the current bins are truly poor fits
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 3.0; // first bin is always worth it
        } else {
            score += 1.5 * (open_bins_count as f64).sqrt(); // slight penalty that grows
        }
    }

    // Progress‑based relaxation
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.25 {
        score += 1.0;
    } else if progress > 0.85 {
        score -= 0.5;
    } else {
        score += (1.0 - progress) * 0.5;
    }

    // Small adjustment for very large streams: loosen penalties for large residuals
    if total_items > 10_000 && post_residual > 80 {
        score -= 1.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // --- 1. Residual contribution -------------------------------------------------
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let mut score = 0.9 * post_residual as f64; // baseline proportional to free space

    // small gaps are sometimes desirable for tight packing
    if post_residual <= 5 {
        score -= 0.7;
    }

    // penalize very large gaps
    if post_residual > 70 {
        score += 0.004 * (post_residual as f64 - 70.0).powi(2);
    }

    // --- 2. Look‑ahead with next item ---------------------------------------------
    if post_residual >= next_item_size {
        // good fit, reward a comfortable margin
        score += 1.8 * ((post_residual - next_item_size) as f64).sqrt();
    } else {
        // gap too tight, penalise
        score += 3.5 * ((next_item_size - post_residual) as f64).sqrt();
    }

    // --- 3. Open‑bin pressure ------------------------------------------------------
    score += 0.35 * open_bins_count as f64;
    if open_bins_count > 12 {
        score += 6.0;
    }

    // --- 4. Fitting‑bins incentive --------------------------------------------------
    if fitting_bins_count >= 6 {
        score -= 2.2;
    } else if fitting_bins_count == 1 {
        score -= 3.8;
    }
    // additional soft reward for many fitting bins
    score -= (fitting_bins_count as f64).powi(2) * 0.015;

    // --- 5. New‑bin handling --------------------------------------------------------
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // grow sub‑linearly with more bins
        score += 2.4 * (open_bins_count as f64).powf(0.55);
    }

    // --- 6. Mean‑residual alignment -------------------------------------------------
    let mean_ratio = mean_residual / bin_capacity as f64;
    let diff_ratio = (residual_ratio - mean_ratio).abs();
    if diff_ratio > 0.12 {
        score += diff_ratio * 22.0;
    } else {
        score -= 0.35;
    }

    // item‑size synergy: large items with very small residuals are undesirable
    if item_size > bin_capacity / 2 && post_residual < (bin_capacity / 4) {
        score += 2.5;
    }

    // --- 7. Progress‑based relaxation ----------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress).powi(2) * 1.6;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the residual after placing the item
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // 1. Gap‑sensitivity: heavily penalise gaps that cannot accommodate the
    //    next item, but also reward large gaps when the next item is very
    //    large (look‑ahead).
    // ------------------------------------------------------------------
    if post_residual < next_item_size {
        // Gap too small – add a linear penalty amplified by 4.0
        score += (next_item_size - post_residual) as f64 * 4.0;
    } else if next_item_size > 80 && post_residual < 20 {
        // Next item is huge but we still have a small gap – discourage this bin
        score += 15.0;
    }

    // Very small residuals are usually a waste of space
    if post_residual < 5 {
        score += 8.0;
    }

    // ------------------------------------------------------------------
    // 2. Open‑bin pressure: keep the number of partially filled bins
    //    low, but be generous when many bins are already open.
    // ------------------------------------------------------------------
    score += 0.3 * open_bins_count as f64;
    if open_bins_count > 10 {
        score += 5.0;
    }

    // ------------------------------------------------------------------
    // 3. Fitting‑bins incentive: if many bins can fit the item, prefer them.
    // ------------------------------------------------------------------
    if fitting_bins_count > 5 {
        score -= 2.0;
    }
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // ------------------------------------------------------------------
    // 4. New‑bin handling: penalise opening a fresh bin unless there
    //    are no other options.
    // ------------------------------------------------------------------
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 2.0 * open_bins_count as f64;
    }

    // ------------------------------------------------------------------
    // 5. Mean‑residual alignment: prefer bins whose residual is close to
    //    the global mean.
    // ------------------------------------------------------------------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff > 5.0 {
        // The farther from the mean, the higher the penalty
        score += mean_diff * 0.05;
    } else {
        // Slight reward for being close to the mean
        score -= 0.5;
    }

    // ------------------------------------------------------------------
    // 6. Large residual quadratic penalty: discourage very large gaps.
    // ------------------------------------------------------------------
    if post_residual > 30 {
        score += 0.001 * (post_residual as f64).powi(2);
    }

    // ------------------------------------------------------------------
    // 7. Progress‑based relaxation: towards the end we tolerate
    //    partially filled bins more.
    // ------------------------------------------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 1.5;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // ---- 1. Basic residual weight ---------------------------------------
    let mut score = 0.8 * post_residual as f64;

    // Small gaps are sometimes useful for tight packing
    if post_residual <= 3 {
        score -= 1.0;
    }

    // Penalise very large gaps aggressively
    if post_residual > 50 {
        score += 0.002 * (post_residual as f64 - 50.0).powi(2);
    }

    // ---- 2. Gap‑sensitivity with look‑ahead -----------------------------
    if post_residual < next_item_size {
        score += 3.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 90 && post_residual < 10 {
        score += 12.0;
    }

    // ---- 3. Open‑bin pressure ------------------------------------------
    score += 0.25 * open_bins_count as f64;
    if open_bins_count > 8 {
        score += 4.0;
    }

    // ---- 4. Fitting‑bins incentive ------------------------------------
    if fitting_bins_count >= 4 {
        score -= 1.5;
    }
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // ---- 5. New‑bin handling ------------------------------------------
    if bin_residual == bin_capacity && open_bins_count > 0 {
        // Sub‑linear growth to avoid over‑penalising when many bins exist
        score += 1.8 * (open_bins_count as f64).powf(0.6);
    }

    // ---- 6. Mean‑residual alignment ------------------------------------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff > 8.0 {
        score += mean_diff * 0.04;
    } else {
        score -= 0.4;
    }

    // ---- 7. Progress‑based relaxation ----------------------------------
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * 1.2;

    score
}

pub fn score_bin(
