    }

    // Residual ratio bonus/penalty
    let ratio = post_residual as f64 / bin_capacity as f64;
    if ratio > 0.85 {
        score += 12.0 * (ratio - 0.85);
    } else if ratio < 0.15 {
        score -= 4.0 * (0.15 - ratio);
    }

    // Look‑ahead handling – penalise gaps that would force a future item
    if next_item_size > post_residual {
        score += 3.5 * (next_item_size - post_residual) as f64;
    } else {
        // Slight reward for leaving a gap close to the next item
        score -= 0.8 * ((next_item_size as f64 - post_residual as f64).abs());
    }

    // Align with the mean residual – tighter packing gets a bonus
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    if mean_diff < 5.0 {
        score -= 1.5;
    } else {
        score += 0.02 * mean_diff;
    }

    // Pressure from many open bins – encourage using existing bins
    score += 0.25 * open_bins_count as f64;
    if open_bins_count > 12 {
        score += 4.0;
    }

    // Incentive for bins that can fit many items
    if fitting_bins_count >= 6 {
